const fs=require("fs");
const ids=["01-skeleton","02-encoder","03-decoder","04-autoregressive","05-dataflow","06-tokenize","07-embed-position","08-encoder-stack","09-decoder-stack","10-linear-softmax","11-weight-sharing","12-recap"];
const durs=[18.3,23.1,24.1,33.3,22.4,23.7,37.0,37.1,32.3,23.6,21.2,31.4];
let bad=0;
ids.forEach((id,i)=>{
  const p=`compositions/frames/${id}.html`;
  const issues=[];
  let h="";
  try{h=fs.readFileSync(p,"utf8");}catch(e){console.log(id,"MISSING");bad++;return;}
  const t=h.trim();
  if(!t.startsWith("<template")) issues.push("no template start");
  if(!t.endsWith("</template>")) issues.push("no template end");
  if(!/<!doctype|<html|<body/i.test(t)===false) issues.push("full-document markup");
  if(!h.includes(`data-composition-id="${id}"`)) issues.push("comp-id mismatch");
  if(!h.includes("data-width=\"1920\"")||!h.includes("data-height=\"1080\"")) issues.push("missing dims");
  if(!h.includes(`data-duration="${durs[i]}"`)) issues.push("duration mismatch (want "+durs[i]+")");
  if(!h.includes(`window.__timelines["${id}"]`)) issues.push("timeline not registered");
  if(/<audio|<video/i.test(h)) issues.push("media element");
  if(/script\s+src=/i.test(h)) issues.push("external script");
  if(!h.includes("NotoSansSC-Variable.ttf")) issues.push("no @font-face");
  if(/Math\.random|Date\.now|performance\.now/.test(h)) issues.push("nondeterministic");
  if(/class="clip"/.test(h)===false) issues.push("no clip element");
  if(/data-track-index/.test(h)===false) issues.push("no track index");
  const mj=`compositions/frames/${id}.motion.json`;
  if(!fs.existsSync(mj)) issues.push("no motion.json"); else { try{JSON.parse(fs.readFileSync(mj,"utf8"));}catch(e){issues.push("bad motion.json");} }
  if(issues.length){bad++;console.log(id.padEnd(20),"✗",issues.join("; "));} else console.log(id.padEnd(20),"✓",(h.length/1024).toFixed(1)+"KB");
});
console.log(bad===0?"ALL FRAMES PASS STRUCTURE":"ISSUES: "+bad);
'

